import math
class Shape:
    name = "Shape"
    def area(self):
        return 0
    def describe(self):
        a = self.area()
        val = round(a, 2)
        return f"{self.name} with area {val}"
class Rectangle(Shape):
    name = "Rectangle"
    def __init__(self, w, h):
        self.w = w
        self.h = h
    def area(self):
        return self.w * self.h
class Square(Rectangle):
    name = "Square"
    def __init__(self, side):
        super().__init__(side, side)
class Circle(Shape):
    name = "Circle"
    def __init__(self, r):
        self.r = r
    def area(self):
        return math.pi * self.r * self.r
def total_area(shapes):
    total = 0
    for i in range(len(shapes)):
        obj = shapes[i]
        total = total + obj.area()
    return round(total, 2)

